const cells = createTransientView(
  graph,
  'cells',
  'uint32x2',
  places.length,
  Buffer.STORAGE | Buffer.COPY_SRC
);
graph.add(
  new GPUPointToCell({
    family: 'h3',
    resolution: 9, // cells of about 0.1 km²
    positions: places, // longitude/latitude degrees
    output: {cells} // 64-bit keys as (low, high) uint32 words
  })
);
